class Skill{final String id,name;final double mastery;const Skill(this.id,this.name,this.mastery);factory Skill.fromMap(Map<String,dynamic>m)=>Skill("${m['id']??''}","${m['name']??m['id']??'Skill'}",(m['mastery']as num? ??0).toDouble());}
class LearnerTwin{final int grade,streak,xp,weeklyMinutes;final String language;final List<Skill> skills;const LearnerTwin({required this.grade,required this.streak,required this.xp,required this.weeklyMinutes,required this.language,required this.skills});factory LearnerTwin.fromMap(Map<String,dynamic>m)=>LearnerTwin(grade:(m['grade']as num? ??8).toInt(),streak:(m['streak']as num? ??0).toInt(),xp:(m['xp']as num? ??0).toInt(),weeklyMinutes:(m['weeklyMinutes']as num? ??0).toInt(),language:"${m['language']??'English'}",skills:((m['skills']as List?)??[]).map((x)=>Skill.fromMap(Map<String,dynamic>.from(x))).toList());}